"""Pixel Arena level pathing: bots walk a tile map painted in primary colors."""

import heapq

Cell = tuple[int, int]  # (row, col)

ENTER_COST = {".": 1, "D": 3, "S": 1, "G": 1}


def find_path(grid: list[str]) -> list[Cell] | None:
    """Cheapest 4-neighbour path from 'S' to 'G', both inclusive.

    '.' floor costs 1 to enter, 'D' door costs 3, '#' is a wall, 'S'/'G' cost 1.
    Return None when G is unreachable.
    """
    start = None
    goal = None
    for row, line in enumerate(grid):
        for col, tile in enumerate(line):
            if tile == "S" and start is None:
                start = (row, col)
            elif tile == "G" and goal is None:
                goal = (row, col)

    if start is None or goal is None:
        return None

    # Dijkstra: doors make step count unreliable, so track entry cost instead.
    costs = {start: 0}
    previous: dict[Cell, Cell] = {}
    frontier: list[tuple[int, Cell]] = [(0, start)]

    while frontier:
        cost, cell = heapq.heappop(frontier)
        if cost > costs.get(cell, float("inf")):
            continue
        if cell == goal:
            break

        row, col = cell
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            neighbour = (row + dr, col + dc)
            nr, nc = neighbour
            if not (0 <= nr < len(grid) and 0 <= nc < len(grid[nr])):
                continue
            tile = grid[nr][nc]
            if tile == "#" or tile not in ENTER_COST:
                continue
            new_cost = cost + ENTER_COST[tile]
            if new_cost < costs.get(neighbour, float("inf")):
                costs[neighbour] = new_cost
                previous[neighbour] = cell
                heapq.heappush(frontier, (new_cost, neighbour))

    if goal not in costs:
        return None

    path = [goal]
    while path[-1] != start:
        path.append(previous[path[-1]])
    path.reverse()
    return path

